#include <stdio.h>
#include <string.h>

// Define a structure to store the commands and their parameters
struct Command {
  char *name;
  int (*func)();
  int param_count;
  char **params;
};

// Define the commands
struct Command commands[] = {
  {"hello", &print_hello, 0, NULL},
  {"world", &print_world, 0, NULL},
  {"add", &add, 2, {"x", "y"}}
};

// Define the maximum number of commands
#define MAX_COMMANDS 10

// Initialize the command table
void init_commands(void) {
  int i;
  for (i = 0; i < MAX_COMMANDS; i++) {
    commands[i].name = NULL;
    commands[i].func = NULL;
    commands[i].param_count = 0;
    commands[i].params = NULL;
  }
}

// Print a message to the console
void print_message(const char *message) {
  printf("%s", message);
}

// Print "hello" to the console
void print_hello(void) {
  print_message("hello");
}

// Print "world" to the console
void print_world(void) {
  print_message("world");
}

// Add two numbers together
void add(int x, int y) {
  int sum = x + y;
  print_message("The sum of %d and %d is %d", x, y, sum);
}

// Print the help message
void print_help(void) {
  printf("Available commands: \n");
  for (int i = 0; i < MAX_COMMANDS; i++) {
    if (commands[i].name) {
      printf("\t%s\n", commands[i].name);
    }
  }
  printf("Usage: arduino-cli [command] [parameters]\n");
}

